import React, { useEffect, useState } from "react";
import DashboardLayout from "../components/DashboardLayout";
import api from "../services/api";
import { useAuth } from "../context/AuthContext";

const Attendance = () => {
  const { user } = useAuth();
  const isTeacher = user?.role === "teacher";
  const [students, setStudents] = useState([]);
  const [records, setRecords] = useState([]);
  const [statusMap, setStatusMap] = useState({});
  const [date, setDate] = useState(new Date().toISOString().slice(0, 10));
  const [month, setMonth] = useState(new Date().toISOString().slice(0, 7));
  const [year, setYear] = useState(String(new Date().getFullYear()));
  const [filterMode, setFilterMode] = useState("date");
  const [studentForm, setStudentForm] = useState({ name: "", roll_number: "", parent_email: "" });
  const [editingStudentId, setEditingStudentId] = useState(null);

  const getFilterParams = () => {
    if (filterMode === "month") {
      return { month };
    }
    if (filterMode === "year") {
      return { year };
    }
    return { date };
  };

  const loadData = async () => {
    if (isTeacher) {
      const [studentRes, attendanceRes] = await Promise.all([
        api.get("/teacher/students"),
        api.get("/teacher/attendance", { params: getFilterParams() }),
      ]);
      setStudents(studentRes.data.students);
      setRecords(attendanceRes.data.records);
    } else {
      const attendanceRes = await api.get("/attendance/history", { params: getFilterParams() });
      setStudents([]);
      setRecords(attendanceRes.data.records);
    }
  };

  useEffect(() => {
    loadData();
  }, [date, month, year, filterMode, user?.role]);

  const handleStatusChange = (studentId, value) => {
    setStatusMap((prev) => ({ ...prev, [studentId]: value }));
  };

  const submitAttendance = async () => {
    if (!isTeacher) {
      return;
    }

    const recordsToSubmit = Object.entries(statusMap)
      .filter(([, value]) => value)
      .map(([studentId, value]) => ({ student_id: Number(studentId), status: value }));

    if (recordsToSubmit.length === 0) {
      return;
    }

    await api.post("/teacher/mark-attendance", { records: recordsToSubmit, date });
    setStatusMap({});
    await loadData();
  };

  const onStudentFormChange = (event) => {
    setStudentForm((prev) => ({ ...prev, [event.target.name]: event.target.value }));
  };

  const addStudentToClass = async (event) => {
    event.preventDefault();
    if (!studentForm.name || !studentForm.roll_number || !studentForm.parent_email) {
      return;
    }

    if (editingStudentId) {
      await api.put(`/teacher/students/${editingStudentId}`, studentForm);
      setEditingStudentId(null);
    } else {
      await api.post("/teacher/students", studentForm);
    }

    setStudentForm({ name: "", roll_number: "", parent_email: "" });
    await loadData();
  };

  const editStudent = (student) => {
    setEditingStudentId(student.id);
    setStudentForm({
      name: student.name || "",
      roll_number: student.roll_number || "",
      parent_email: student.parent_email || "",
    });
  };

  const cancelEditStudent = () => {
    setEditingStudentId(null);
    setStudentForm({ name: "", roll_number: "", parent_email: "" });
  };

  const removeStudent = async (student) => {
    const confirmed = window.confirm(`Remove student ${student.name}?`);
    if (!confirmed) {
      return;
    }
    await api.delete(`/teacher/students/${student.id}`);
    await loadData();
  };

  return (
    <DashboardLayout title="Attendance">
      <div className="panel">
        <label>Attendence Filter</label>
        <div className="filter-mode-row">
          <button
            type="button"
            className={`filter-mode-btn ${filterMode === "date" ? "active" : ""}`}
            onClick={() => setFilterMode("date")}
          >
            Calendar Date
          </button>
          <button
            type="button"
            className={`filter-mode-btn ${filterMode === "month" ? "active" : ""}`}
            onClick={() => setFilterMode("month")}
          >
            Monthly
          </button>
          <button
            type="button"
            className={`filter-mode-btn ${filterMode === "year" ? "active" : ""}`}
            onClick={() => setFilterMode("year")}
          >
            Yearly
          </button>
        </div>
        {filterMode === "date" && (
          <>
            <label>Date</label>
            <input type="date" value={date} onChange={(event) => setDate(event.target.value)} />
          </>
        )}
        {filterMode === "month" && (
          <>
            <label>Month</label>
            <input type="month" value={month} onChange={(event) => setMonth(event.target.value)} />
          </>
        )}
        {filterMode === "year" && (
          <>
            <label>Year</label>
            <input type="number" min="2000" max="2100" value={year} onChange={(event) => setYear(event.target.value)} />
          </>
        )}
      </div>
      {isTeacher && (
        <>
          <div className="panel">
            <h3>{editingStudentId ? "Change Student Data" : "Add Student To Your Class"}</h3>
            <form className="grid-form" onSubmit={addStudentToClass}>
              <input name="name" value={studentForm.name} onChange={onStudentFormChange} placeholder="Student Name" />
              <input name="roll_number" value={studentForm.roll_number} onChange={onStudentFormChange} placeholder="Roll Number" />
              <input
                name="parent_email"
                value={studentForm.parent_email}
                onChange={onStudentFormChange}
                placeholder="Parent Email"
                type="email"
              />
              <button type="submit">{editingStudentId ? "Save Changes" : "Add Student"}</button>
              {editingStudentId && (
                <button type="button" className="table-action-btn" onClick={cancelEditStudent}>
                  Cancel
                </button>
              )}
            </form>
            <div className="table-wrap" style={{ marginTop: 12 }}>
              <table className="table">
                <thead>
                  <tr>
                    <th>Name</th>
                    <th>Roll</th>
                    <th>Parent Email</th>
                    <th>Actions</th>
                  </tr>
                </thead>
                <tbody>
                  {students.length > 0 ? (
                    students.map((student) => (
                      <tr key={`teacher-student-${student.id}`}>
                        <td>{student.name}</td>
                        <td>{student.roll_number}</td>
                        <td>{student.parent_email}</td>
                        <td>
                          <div className="table-actions">
                            <button type="button" className="table-action-btn" onClick={() => editStudent(student)}>
                              Change
                            </button>
                            <button type="button" className="table-action-btn danger" onClick={() => removeStudent(student)}>
                              Remove
                            </button>
                          </div>
                        </td>
                      </tr>
                    ))
                  ) : (
                    <tr>
                      <td colSpan="4" className="empty-cell">
                        No students in your class
                      </td>
                    </tr>
                  )}
                </tbody>
              </table>
            </div>
          </div>
          <div className="panel">
            <h3>Mark Attendance</h3>
            <div className="attendance-list">
              {students.map((student) => (
                <div className="attendance-row" key={student.id}>
                  <span>
                    {student.name} ({student.class_grade}-{student.division} - {student.roll_number})
                  </span>
                  <div className="status-buttons">
                    {["Present", "Absent", "Late"].map((status) => (
                      <button
                        key={status}
                        type="button"
                        className={statusMap[student.id] === status ? "active-status" : ""}
                        onClick={() => handleStatusChange(student.id, status)}
                      >
                        {status}
                      </button>
                    ))}
                  </div>
                </div>
              ))}
            </div>
            <button className="submit-btn" onClick={submitAttendance}>
              Submit Attendance
            </button>
          </div>
        </>
      )}
      <div className="panel">
        <h3>Attendance History</h3>
        <div className="table-wrap">
          <table className="table">
            <thead>
              <tr>
                <th>Date</th>
                <th>Student</th>
                <th>Class</th>
                <th>Status</th>
              </tr>
            </thead>
            <tbody>
              {records.length > 0 ? (
                records.map((record) => (
                  <tr key={record.id}>
                    <td>{record.date}</td>
                    <td>{record.student?.name}</td>
                    <td>{record.student?.class_grade}-{record.student?.division}</td>
                    <td>{record.status}</td>
                  </tr>
                ))
              ) : (
                <tr>
                  <td colSpan="4" className="empty-cell">
                    No attendance records
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>
    </DashboardLayout>
  );
};

export default Attendance;
